{
  "title": "The Mirror Bridge Rescue",
  "gate_token": "eEJhYF1LkT21a5RJNkRSgg",
  "scenes": [
    {
      "scene_number": 1,
      "caption": "The team gathers at the ruined city gates.",
      "visual_description": "Crumpled iron gates hang askew, old royal banners torn and faded flutter in the wind. The glass diver adjusts his helmet while Mara studies a frayed map. The oracle lamp flickers on a stone post, and the sleeping tax collector snores against a broken pillar. The tin fox sniffs the ground.",
      "characters": ["glass_diver", "mara_the_cartographer", "oracle_lamp", "sleeping_tax_collector", "tin_fox"]
    },
    {
      "scene_number": 2,
      "caption": "The oracle lamp warns of a cursed tower ahead.",
      "visual_description": "A twisted tower looms in mist, its windows glowing with pale blue light. The lamp's flame eye narrows. Mara points at the tower on her map. The glass diver peers through a cracked windowpane.",
      "characters": ["oracle_lamp", "mara_the_cartographer", "glass_diver"]
    },
    {
      "scene_number": 3,
      "caption": "The tin fox scouts a hidden passage beneath the city wall.",
      "visual_description": "Beneath the wall, a rusted grate half-covered by rubble. The tin fox's blue eyes gleam as it pries open the grate with its metal jaws. Mara notes the spot on her map.",
      "characters": ["tin_fox", "mara_the_cartographer"]
    },
    {
      "scene_number": 4,
      "caption": "The glass diver swims through a mirror into a sealed courtyard.",
      "visual_description": "A large, tarnished mirror leans against a broken archway. The glass diver presses his helmet against it, then steps through like a ripple. The courtyard beyond is littered with faded royal banners.",
      "characters": ["glass_diver"]
    },
    {
      "scene_number": 5,
      "caption": "Mara deciphers a map left by a previous rescuer.",
      "visual_description": "In a dusty alcove, Mara unrolls a brittle parchment. The ink glows faintly, showing paths and a marked 'X' near the central keep. The oracle lamp holds its flame close to illuminate the map.",
      "characters": ["mara_the_cartographer", "oracle_lamp"]
    },
    {
      "scene_number": 6,
      "caption": "The sleeping tax collector wakes briefly to stamp a useless permission slip.",
      "visual_description": "The tax collector stirs, blinks, and pulls a stamp from his sleeve. He stamps a blank paper, then falls back asleep on his ledger pillow. The tin fox nudges the paper with its nose.",
      "characters": ["sleeping_tax_collector", "tin_fox"]
    },
    {
      "scene_number": 7,
      "caption": "Armored patrols march past a shattered fountain.",
      "visual_description": "A stone fountain lies in pieces, water trickling through cracks. In the distance, a squad of armored figures clanks past, their visors down. The team hides behind the fountain. The glass diver readies his mirror shard.",
      "characters": ["glass_diver", "mara_the_cartographer", "oracle_lamp", "tin_fox"]
    },
    {
      "scene_number": 8,
      "caption": "The oracle lamp reveals a false magic door.",
      "visual_description": "A grand door carved with runes stands at the end of a corridor. The lamp's flame sputters, showing the door is a glamour – the real door is a crumbling archway to the left. Mara adjusts her direction.",
      "characters": ["oracle_lamp", "mara_the_cartographer"]
    },
    {
      "scene_number": 9,
      "caption": "The tin fox leads the group through a collapsing stairwell.",
      "visual_description": "Narrow stone stairs crumble as each step is taken. The tin fox darts ahead, testing each stair. Dust falls from above. The glass diver catches a falling stone with a mirrored reflection.",
      "characters": ["tin_fox", "glass_diver", "mara_the_cartographer", "oracle_lamp", "sleeping_tax_collector"]
    },
    {
      "scene_number": 10,
      "caption": "Rumors of a dragon prove to be a massive clockwork construct.",
      "visual_description": "In a vast hall, a huge metal beast with wings of brass and gears hangs from chains. Its eyes are dark. The oracle lamp whispers that it is dormant. The sleeping tax collector snores louder.",
      "characters": ["oracle_lamp", "sleeping_tax_collector", "glass_diver", "mara_the_cartographer", "tin_fox"]
    },
    {
      "scene_number": 11,
      "caption": "Mara finds the captive behind a locked gate.",
      "visual_description": "A barred gate at the end of a long corridor. Behind it, a figure in tattered clothes stands. Mara presses her map to the bars. The glass diver begins to melt a mirror into a key.",
      "characters": ["mara_the_cartographer", "glass_diver"]
    },
    {
      "scene_number": 12,
      "caption": "The glass diver uses a mirror to unlock the gate.",
      "visual_description": "The diver holds a polished shard, reflecting the lock mechanism. Light bends and the lock clicks open. The gate swings with a groan. The captive steps forward – a weary mapmaker.",
      "characters": ["glass_diver", "mara_the_cartographer"]
    },
    {
      "scene_number": 13,
      "caption": "The oracle lamp guides the group through a fog of illusions.",
      "visual_description": "Thick mist fills a circular chamber, showing false exits and phantom figures. The lamp's steady flame cuts through, revealing the true path. The tin fox follows closely.",
      "characters": ["oracle_lamp", "tin_fox", "glass_diver", "mara_the_cartographer", "sleeping_tax_collector"]
    },
    {
      "scene_number": 14,
      "caption": "Armored patrols block the main corridor.",
      "visual_description": "A line of armored figures stands motionless, blocking the way. Their visors glow. The sleeping tax collector sleepwalks forward and stamps one's chest – it freezes. The others remain still.",
      "characters": ["sleeping_tax_collector", "mara_the_cartographer", "glass_diver", "oracle_lamp", "tin_fox"]
    },
    {
      "scene_number": 15,
      "caption": "The final escape bridge is guarded by a mirror trap.",
      "visual_description": "A stone bridge arches over a chasm. At its midpoint, a floating mirror shard reflects the team. The glass diver realizes stepping into the reflection would trap them. He shatters the shard with his helmet.",
      "characters": ["glass_diver", "mara_the_cartographer", "oracle_lamp", "sleeping_tax_collector", "tin_fox"]
    },
    {
      "scene_number": 16,
      "caption": "The group crosses the bridge as it begins to crumble.",
      "visual_description": "Stones fall from the bridge into the darkness below. The tin fox runs ahead, the sleeping tax collector is carried by Mara. The lamp's flame flickers violently. The glass diver reflects fallen stones to create a path.",
      "characters": ["glass_diver", "mara_the_cartographer", "oracle_lamp", "sleeping_tax_collector", "tin_fox"]
    },
    {
      "scene_number": 17,
      "caption": "The team reaches the far side and looks back.",
      "visual_description": "The ruined city looms behind them, the bridge collapsing into the mist. The sky is pale grey. The rescued mapmaker thanks them. The oracle lamp's flame steadies.",
      "characters": ["glass_diver", "mara_the_cartographer", "oracle_lamp", "sleeping_tax_collector", "tin_fox"]
    },
    {
      "scene_number": 18,
      "caption": "The tin fox finds a safe road home.",
      "visual_description": "A narrow path winds through hills, marked by a small metal sign. The tin fox's tail winds down as it points the way. Mara folds her map, smiling. The group begins the journey home.",
      "characters": ["tin_fox", "mara_the_cartographer", "glass_diver", "oracle_lamp", "sleeping_tax_collector"]
    }
  ]
}

